solution:
use xiom.io;

use xiom.string;
fn c_to_f(c_str: Str) -> Result[Float64, Str] {
  let celsius = string.str_to_float(c_str)?;
  if celsius < -273.15 {
    return Err("Temperature below absolute zero");
  }
  if celsius > 1000.0 {
    return Err("Temperature exceeds maximum");
  }
  let fahrenheit = celsius * 9.0 / 5.0 + 32.0;
  return Ok(fahrenheit);
}

fn main() -> Int {
  match c_to_f("100") {
    Ok(f) => { return (f * 10.0) as Int; }
    Err(_) => { return -1; }
  }
}
